#!/usr/bin/env python3
"""Simulates the job graph of .github/workflows/release.yml (generated by dist) with GitHub
Actions `needs` / `if` semantics, and checks that `host` (the job that creates the GitHub
Release) runs only when every gate passed.

The gap this guards: `host` accepts `skipped` as well as `success` from the jobs it needs. If a
gate fails in a way that makes the build jobs skip, `host` would run with no artifacts.

Needs PyYAML. Usage: scripts/test-release-gate.py [path/to/release.yml]
"""
import re
import sys

import yaml

path = sys.argv[1] if len(sys.argv) > 1 else ".github/workflows/release.yml"
with open(path) as f:
    jobs = yaml.safe_load(f)["jobs"]

SPECIAL = re.compile(r"\b(failure|cancelled|success)\(\)")


def needs_of(job):
    n = job.get("needs", [])
    return [n] if isinstance(n, str) else list(n)


def evaluate_if(expr, results):
    """Evaluates the subset of the expression language dist generates."""
    e = expr.strip()
    e = re.sub(r"^\$\{\{|\}\}$", "", e).strip()
    # Facts for a tag push: the plan job succeeded, is publishing, and found artifacts to build.
    e = re.sub(r"fromJson\(needs\.plan\.outputs\.val\)[\w.]*\s*!=\s*null", "True", e)
    e = re.sub(r"fromJson\(needs\.plan\.outputs\.val\)[\w.]*\s*==\s*'[^']*'", "True", e)
    e = e.replace("needs.plan.outputs.publishing == 'true'", "True")
    e = e.replace("always()", "True")
    e = re.sub(r"needs\.([\w-]+)\.result", lambda m: repr(results[m.group(1)]), e)
    e = e.replace("&&", " and ").replace("||", " or ")
    if re.search(r"needs\.|fromJson|\(\)", e):
        raise SystemExit(f"cannot simulate expression: {expr}")
    return bool(eval(e, {"__builtins__": {}}, {"True": True}))  # noqa: S307 (own workflow file)


def simulate(forced):
    """Returns {job: result}. `forced` maps job -> result for jobs that would run."""
    results = {"plan": "success"}
    pending = [j for j in jobs if j != "plan"]
    while pending:
        progressed = False
        for name in list(pending):
            job = jobs[name]
            needs = needs_of(job)
            if any(n not in results for n in needs):
                continue
            expr = job.get("if")
            implicit_success = all(results[n] == "success" for n in needs)
            if expr is None:
                runs = implicit_success
            elif re.search(r"always\(\)|failure\(\)|cancelled\(\)", str(expr)):
                runs = evaluate_if(str(expr), results)
            else:
                runs = implicit_success and evaluate_if(str(expr), results)
            results[name] = forced.get(name, "success") if runs else "skipped"
            pending.remove(name)
            progressed = True
        if not progressed:
            raise SystemExit(f"cycle or missing job among {pending}")
    return results


gates = [j for j in jobs if j.startswith("custom-")] + ["build-local-artifacts", "build-global-artifacts"]
failures = []


def expect(label, forced, host_runs):
    r = simulate(forced)
    ran = r["host"] != "skipped"
    mark = "ok  " if ran == host_runs else "FAIL"
    print(f"{mark} {label}: host {'runs' if ran else 'is skipped'}")
    if ran != host_runs:
        failures.append(label)


expect("all jobs succeed", {}, True)
for g in gates:
    expect(f"{g} fails", {g: "failure"}, False)

for needed in ("custom-ci", "custom-release-check", "custom-release-smoke"):
    if needed not in jobs:
        failures.append(f"{needed} job missing from {path}")
        print(f"FAIL {needed} job missing")

if failures:
    sys.exit(f"release gate test failed: {failures}")
print("release gate: ok")
